using System;

public class Triangle
{
    public static double CalculateArea(double side1, double side2, double side3)
    {
        // Check if the given side lengths form a valid triangle
        if (!IsValidTriangle(side1, side2, side3))
        {
            throw new ArgumentException("Invalid triangle: the given side lengths do not form a triangle.");
        }

        // Calculate the semi-perimeter
        double semiPerimeter = (side1 + side2 + side3) / 2;

        // Calculate the area using Heron's formula
        double area = Math.Sqrt(semiPerimeter * (semiPerimeter - side1) * (semiPerimeter - side2) * (semiPerimeter - side3));

        return area;
    }

    private static bool IsValidTriangle(double side1, double side2, double side3)
    {
        // Check if the sum of any two sides is greater than the third side
        return side1 + side2 > side3 && side2 + side3 > side1 && side1 + side3 > side2;
    }
}
```

